import configparser
import os

def get_config(path):
    """
    Returns the config object
    """
    config = configparser.ConfigParser()
    config.read(path)
    return config

def update_setting(path, section, setting, value):
    """
    Update a setting
    """
    if not os.path.exists(path):
        print("Oops!  File to make changes is not found")
    else:
        config = get_config(path)
        config.set(section, setting, value)
        with open(path, "w") as config_file:
            config.write(config_file,space_around_delimiters=False)

def traverse(file_name:str):
    try:
        if not os.path.exists(file_name):
            print("Oops!  File not found")
        else:
            with open(file_name) as source:
                for i in source.read().splitlines():
                    path,section,key,value = i.split(",")
                    update_setting(path.strip(),section.strip(),key.strip(),value.strip())
    except ValueError:
         print("Incorrect file path")

if __name__ == "__main__":
    file_name = input("Please enter csv file path: ")
    traverse(file_name)


